package com.shale.ui.controller;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
final class UserManagementPopupContractTest {
 private static String read(String file)throws Exception{return Files.readString(Path.of("src/main/"+file));}
 @Test void settingsRowIsCompactManageLauncher()throws Exception{String fxml=read("resources/fxml/settings.fxml"),controller=read("java/com/shale/ui/controller/SettingsController.java");assertTrue(fxml.contains("fx:id=\"userManagementRow\" title=\"User Management\" description=\"Manage users for the current tenant.\" actionText=\"Manage\""));assertFalse(fxml.contains("userAdministrationSection"));assertFalse(fxml.contains("userManagementTable"));assertTrue(controller.contains("bind(userManagementRow, this::onManageUsers)"));assertTrue(controller.contains("new UserManagementLauncher(userDao, settingsLoadExecutor)"));}
 @Test void authorizationRequiresCompleteAdminContextAndCapturedIdentity()throws Exception{String controller=read("java/com/shale/ui/controller/SettingsController.java");assertTrue(controller.contains("setVisibleManaged(userManagementRow, hasAdminContext() && userDao != null)"));assertTrue(controller.contains("final int tenantId = requireTenantId()"));assertTrue(controller.contains("final int actorUserId = requireActorUserId()"));}
 @Test void paneOwnsAsyncLifecycleWithoutOwningExecutor()throws Exception{String pane=read("java/com/shale/ui/controller/UserManagementPane.java"),launcher=read("java/com/shale/ui/controller/UserManagementLauncher.java");assertTrue(launcher.indexOf("session.show(")<launcher.indexOf("pane.open()"));assertTrue(pane.contains("settingsLoadExecutor.execute"));assertTrue(pane.contains("disposed.get()"));assertTrue(pane.contains("changes.markCommitted()"));assertTrue(pane.contains("loadManagedUsersAsync(success)"));assertFalse(pane.contains("Executors.new"));assertFalse(pane.contains(".shutdown"));assertFalse(pane.toLowerCase().contains("newpassword)"+" +"));}
}
